    "corrected_c_code": "#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_pop_successful_pop_without_shrink(void) {
    DArrayStack *stack = NULL;
    int success = 0;
    int popped_value = 0;

    // Create a stack with even capacity (e.g., 4) and push elements.
    // For path 14: stack not NULL, top != -1, success pointer provided,
    // capacity even, top > (capacity/2)-1 (so shrink condition false).
    // Let's use capacity = 4, push 3 elements (top = 2).
    // Condition: top <= (capacity/2)-1 ? (2 <= (4/2)-1 = 2 <= 1) false.
    // So shrink_array is NOT called.
    stack = malloc(sizeof(DArrayStack));
    TEST_ASSERT_NOT_NULL(stack);
    stack->capacity = 4;
    stack->top = -1;
    stack->arrPtr = malloc(4 * sizeof(int));
    TEST_ASSERT_NOT_NULL(stack->arrPtr);

    // Push three values.
    int push_result = push(stack, 10);
    TEST_ASSERT_EQUAL_INT(0, push_result); // top becomes 0
    push_result = push(stack, 20);
    TEST_ASSERT_EQUAL_INT(1, push_result); // top becomes 1
    push_result = push(stack, 30);
    TEST_ASSERT_EQUAL_INT(2, push_result); // top becomes 2

    // Verify initial state.
    TEST_ASSERT_EQUAL_INT(4, stack->capacity);
    TEST_ASSERT_EQUAL_INT(3, stack->top + 1);
    TEST_ASSERT_EQUAL_INT(2, stack->top);

    // Test pop with success pointer.
    popped_value = pop(stack, &success);
    // Ensure shrink_array is not called - verify conditions
    TEST_ASSERT_FALSE((stack->capacity % 2 == 0 && stack->capacity >= 2 && stack->top <= (stack->capacity / 2) - 1));

    // Assertions for path 14.
    TEST_ASSERT_EQUAL_INT(1, success); // success set to 1
    TEST_ASSERT_EQUAL_INT(30, popped_value); // last pushed element
    // Top decremented.
    TEST_ASSERT_EQUAL_INT(1, stack->top);
    // Capacity remains unchanged (no shrink).
    TEST_ASSERT_EQUAL_INT(4, stack->capacity);
    // Size decreased.
    TEST_ASSERT_EQUAL_INT(2, stack->top + 1);
    // The popped element's storage zeroed? (implementation sets arrPtr[old_top] = 0)
    // We can peek at index 2 (old top) if we have a way, but not required.

    // Cleanup.
    free(stack->arrPtr);
    free(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_pop_successful_pop_without_shrink);
    return UNITY_END();
